<?php
use App\Http\Controllers\AuthController;use App\Http\Controllers\EditorController;use App\Http\Controllers\ExportController;use App\Http\Controllers\SupportController;use App\Http\Controllers\AdminController;use Illuminate\Support\Facades\Route;
Route::get('/', fn()=>view('home'))->name('home');Route::get('/pricing',[EditorController::class,'pricing'])->name('pricing');Route::view('/terms','legal.terms')->name('terms');Route::view('/refund-policy','legal.refunds')->name('refunds');Route::view('/privacy','legal.privacy')->name('privacy');Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login/admin',[AuthController::class,'adminLogin'])->middleware('throttle:5,10')->name('login.admin');Route::post('/login/request-otp',[AuthController::class,'requestOtp'])->middleware('throttle:5,10')->name('login.otp');Route::post('/login/verify',[AuthController::class,'verifyOtp'])->middleware('throttle:10,10')->name('login.verify');Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware(['auth','single.editor'])->group(function(){Route::get('/dashboard',[EditorController::class,'dashboard'])->name('dashboard');Route::get('/editor',[EditorController::class,'create'])->name('editor');Route::post('/editor/upload',[EditorController::class,'upload'])->middleware('throttle:10,10')->name('editor.upload');Route::post('/editor/analyze',[EditorController::class,'analyze'])->middleware('throttle:20,10')->name('editor.analyze');Route::post('/editor/save',[EditorController::class,'save'])->middleware('throttle:120,1')->name('editor.save');Route::post('/editor/feedback',[EditorController::class,'feedback'])->middleware('throttle:60,10')->name('editor.feedback');Route::post('/editor/export/{format}',[ExportController::class,'export'])->whereIn('format',['docx','pdf'])->middleware('throttle:10,10')->name('editor.export');Route::post('/editor/heartbeat',[EditorController::class,'heartbeat'])->middleware('throttle:60,1')->name('editor.heartbeat');Route::get('/support',[SupportController::class,'index'])->name('support');Route::post('/support/tickets',[SupportController::class,'create'])->middleware('throttle:10,10')->name('support.create');Route::post('/support/tickets/{ticket}/messages',[SupportController::class,'message'])->middleware('throttle:30,10')->name('support.message');});
Route::middleware(['auth','admin'])->prefix('admin')->name('admin.')->group(function(){Route::get('/',[AdminController::class,'index'])->name('index');Route::post('/pricing',[AdminController::class,'updatePricing'])->name('pricing.update');Route::post('/users/{user}/block',[AdminController::class,'toggleUser'])->name('user.toggle');});
